INSERT INTO `achievement_locale` (`ID`, `locale`, `Description_lang`, `Title_lang`, `Reward_lang`, `VerifiedBuild`) VALUES
(63325, 'deDE', 'Verdient 5 Partikel der Omniumerforschung zur Verwendung im Omniumfoliant.', 'Studien des Omniumfolianten', 'Dekorationsbelohnung: Simulakrum des Omniums der Sonnenwanderer', 68974),
(62903, 'deDE', 'Zerstreut 5 Stürme in Val.', 'Seltsames Klima: Val', 'Haustier-Belohnung: Schaltet Fischstäbchen-Keith zum Kauf frei', 68974),
(63343, 'deDE', 'Schießt in Silbermond mit einem tretbaren Übungsball ein Tor, während Ihr einen Wappenrock der Teilnahme tragt.', 'Tor!', 'Dekorationsbelohnung: Prächtige Kugel von Azeroth, gerahmter Stolz der Horde und gerahmter Stolz der Allianz', 68974),
(61336, 'deDE', 'Ehrt die Flammen von Midnight.', 'Flammenwächter von Midnight', '', 68974),
(61335, 'deDE', 'Ehrt die Flammen von Midnight.', 'Flammenbewahrer von Midnight', '', 68974),
(61936, 'deDE', 'Besiegt die lichtblinde Vorhut in der Leerenspitze auf dem Schwierigkeitsgrad \'Normal\' oder höher, während Euer gesamter Schlachtzug maximale Aura hat.', 'Aura-Farmen', '', 68974),
(61911, 'deDE', 'Besiegt Vaelgor & Ezzorak, nachdem alle Spielercharaktere in der Leerenspitze auf dem Schwierigkeitsgrad \'Normal\' oder höher jede Verbindung der Nullzone innerhalb von 3 Sekunden getrennt haben.', 'Schnipp, schnapp, ab!', '', 68974),
(61514, 'deDE', 'Besiegt den gefallenen König Salhadaar, nachdem alle vor dem Kampf vor ihm niedergekniet haben, in der Leerenspitze auf dem Schwierigkeitsgrad \'Normal\' oder höher.', 'Dann also Verrat', '', 68974),
(61381, 'deDE', 'Besiegt Belo\'ren, Kind von Al\'ar, beim Marsch auf Quel\'Danas auf dem Schwierigkeitsgrad \'Normal\' oder höher, nachdem Ihr das Sonnenbrunnenei mit Licht- und Leerenmagie erfüllt habt.', 'Ei-skalation', '', 68974),
(61346, 'deDE', 'Besiegt die Krone des Kosmos in der Leerenspitze auf dem Schwierigkeitsgrad \'Normal\' oder höher, nachdem Ihr ein fleischiges Monstrum getötet und all sein Fleisch zum Nichts zurückgebracht habt.', 'Wiedersehen macht Freude', '', 68974),
(61611, 'deDE', 'Besiegt den Anbruch der Mitternacht im Marsch auf Quel\'Danas auf dem Schwierigkeitsgrad Mythisch, während Ihr in einer Gildengruppe seid.', 'Gilde - Mythisch: Anbruch der Mitternacht', '', 68974),
(61380, 'deDE', 'Schließt die unten aufgelisteten Schlachtzugserfolge ab:', 'Ruhm des Schlachtzüglers von Midnight', 'Reittier: Schattenhafte(r) Plager(in)', 68974),
(62874, 'deDE', 'Schließt die folgenden Erfolge ab:', 'Eine Reise durch die Sterne', 'Belohnung: Schaltet die nethergeschmiedete Nullpanzerung zum Kauf frei', 68974);
INSERT INTO `adventure_journal_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `ButtonText_lang`, `RewardDescription_lang`, `ContinueDescription_lang`, `VerifiedBuild`) VALUES
(909, 'deDE', 'Omniumfoliant – Neue Informationen', 'Die Magister haben zusätzliche Informationen, die zur Ermächtigung weiterer Runen im Omniumfolianten führen können.', 'Quest annehmen', 'Gewährt ein Partikel der Omniumerforschung, mit dem eine weitere Rune im Omniumfolianten ermächtigt werden kann.', '', 68974);
INSERT INTO `area_table_locale` (`ID`, `locale`, `AreaName_lang`, `VerifiedBuild`) VALUES
(15966, 'deDE', 'Bau von Predaxas', 68974);
INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(4618, 'deDE', 'ENTSPANNUNGSMODUS: AKTIVIERT.\nENTSPANNUNGSPEGEL: MAXIMUM.\nINTERNE TEMPERATUR: NIEDRIG.', '|cFFFFD200Promotion|r |n', 68974),
(4617, 'deDE', 'PRIMÄRZIEL: HELDENTATEN VOLLBRINGEN.\nBEVORZUGTE HELDENTATEN: NERVENKITZEL.\nSEKUNDÄRES ZIEL: HELD WERDEN.\nBEVORZUGTER HELD: BERÜHMT.', '|cFFFFD200Promotion|r |n', 68974),
(4949, 'deDE', 'Ein Überrest von Fyrakks Versuch, Amirdrassil zu verderben.', '|cFFFFD200Verkäufer: |rXydan|n|cFFFFD200Zone: |rValdrakken|n|cFFFFD200Kosten: |r2200|Hcurrency:1166|h|TInterface\\ICONS\\PVECurrency-Justice.blp:0|t|h', 68974),
(5074, 'deDE', 'Anders als die meisten Leerwandler im Leerensturm bevorzugt Silento die Ruhe und den Frieden des Schweigens. Und wenn es sein muss, bringt er dafür die geschwätzigsten seiner Art zum Verstummen.', '|cFFFFD200Erfolge:|r Konfrontationserfolg: Val und Konfrontationserfolg: Naigtal|n|cFFFFD200Verkäufer: |rKifaan|n|cFFFFD200Zonen: |rVal oder Naigtal|n|cFFFFD200Kosten: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(5073, 'deDE', 'Ganz bestrebt, seiner Abstammung gerecht zu werden, ist diese Kleine bereit für ihren Beutezug. Sie wird mit kleinen Spinnen anfangen und sich von dort aus hocharbeiten.', '|cFFFFD200Erfolg:|r Ultradongemetzel|n|cFFFFD200Verkäufer: |rKifaan|n|cFFFFD200Zonen: |rVal oder Naigtal|n|cFFFFD200Kosten: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(4898, 'deDE', 'Gefrorene Fische sind Keiths Lieblingsessen. Habt Ihr welche in der Tasche, habt Ihr gleich einen neuen besten Freund gefunden.', '|cFFFFD200Erfolg: |r Seltsames Klima: Val|n|cFFFFD200Verkäufer: |rKifaan|n|cFFFFD200Zone: |rNaigtal oder Val|n|cFFFFD200Kosten: |r50|Hitem:238365|h|TInterface\\ICONS\\INV_Misc_Fish_41.blp:0|t|h |n|n', 68974);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(317639, 'deDE', 'Kommandant Tala\'saan legt seinen Lichtschleiermantel ab und tritt vor.', '', 68974),
(314421, 'deDE', 'AAAH!', '', 68974),
(314420, 'deDE', 'NEFFE, PASST AUF!', '', 68974),
(314419, 'deDE', 'KEINE HASH\'EY!', '', 68974),
(314418, 'deDE', 'Mit dieser Macht brauchen wir KEINE LOA,', '', 68974),
(314417, 'deDE', 'Nein!', '', 68974),
(314416, 'deDE', 'Lasst es los!', '', 68974),
(314415, 'deDE', 'Das is\' dunkle Magie!', '', 68974),
(314414, 'deDE', 'Zul\'jan!', '', 68974),
(314413, 'deDE', '(grunzt)', '', 68974),
(314412, 'deDE', 'Das hier muss... der Schlüssel sein...', '', 68974),
(314411, 'deDE', 'Gefund\'n!', '', 68974),
(314410, 'deDE', 'Ah!', '', 68974),
(314408, 'deDE', 'wird sie es... bestimmt versteh\'n.', '', 68974),
(314407, 'deDE', '... un\' wenn Ula\'teks Macht Euch gehört,', '', 68974),
(314406, 'deDE', 'Nehmt den Schlüssel, Zul\'jan.', '', 68974),
(314405, 'deDE', 'Wenn sie unsern Onkel sieht...', '', 68974),
(314404, 'deDE', 'Die Loa ham sie komplett unter Kontrolle.', '', 68974),
(314403, 'deDE', 'Was is\' mit meiner Schwester?', '', 68974),
(314402, 'deDE', 'Vollend\'n wir das Werk Eures Großvaters.', '', 68974),
(314401, 'deDE', 'frei von leeren Versprech\'n der Loa.', '', 68974),
(314400, 'deDE', 'Damit unser Volk leb\'n kann,', '', 68974),
(314399, 'deDE', 'un\' ich brauch Eure Hilfe.', '', 68974),
(314398, 'deDE', 'Malacrass,', '', 68974),
(314397, 'deDE', 'Ja...', '', 68974),
(314396, 'deDE', 'Seid Ihr etwa...', '', 68974),
(314395, 'deDE', 'Ihr kanntet meinen Großvater?', '', 68974),
(314394, 'deDE', 'Zul\'jin und ich, wir wollt\'n das ändern...', '', 68974),
(314393, 'deDE', 'Das is\' das Schicksal unseres Volkes.', '', 68974),
(314392, 'deDE', '...doch wo war\'n sie bei seinem letzten Atemzug?', '', 68974),
(314391, 'deDE', 'Ein Leben lang diente er den Loa...', '', 68974),
(314390, 'deDE', 'Tragisch.', '', 68974),
(314389, 'deDE', 'Nein, nein, nein, ich...', '', 68974),
(314388, 'deDE', 'Nein...', '', 68974),
(314387, 'deDE', 'Er is\' tot, Zul\'jan.', '', 68974),
(314386, 'deDE', 'ONKEL!', '', 68974),
(314385, 'deDE', 'Onkel?!', '', 68974),
(314384, 'deDE', '(hustet)', '', 68974),
(310355, 'deDE', 'Ich durchsuche den Morgensternturm nach dem fehlenden Teil. Trefft mich dort, Champion. Und Rommath, viel Glück.', '', 68974),
(317801, 'deDE', '<Tala\'saan denkt über die Frage nach, wobei sein Blick für einen kurzen Augenblick in die Ferne schweift.>\n\nHauptmann Fareeya wird sich nicht an dieser Operation beteiligen.\n\nIch fungiere als ihr Stellvertreter für die in Maellas Mission eingesetzten Lichtgeschmiedeten.\n\nNach dem Verlust des Hochexarchen und zahllosen anderen ist die Armee des Lichts nun mehr als je zuvor auf ihre Führerschaft angewiesen.\n\nZum Glück sind wir nicht ganz allein. Wie Ihr gesehen habt, haben sich uns Baraat und Y\'mera angeschlossen.\n\nEnaara hat nach langem Zögern ihr Einverständnis gegeben, aber auch sie wird mit Sorvos und dem Hauptmann zurückbleiben.', '', 68974),
(317797, 'deDE', '<Tala\'saans Blick wird hart.>\n\nWir haben viele meiner Brüder und Schwestern... an den kreischenden Vortex der Leerenspitze verloren.\n\nViele weitere erlitten Verletzungen, die über das Physische hinausgehen.\n\nIch weiß, was viele von ihnen innerhalb der Spitze heimsuchte, $n. Ihr habt es auch gesehen, nicht wahr? Zorn... Verwirrung... Verzweiflung.\n\nWir haben in diesem Krieg viele gute Seelen verloren. Ich konnte von Fareeya nicht mehr verlangen, als sie ohnehin schon getan hat.', '', 68974),
(317795, 'deDE', 'Ich bin Tala\'saan, Kommandant der Lichtschleier in der Armee des Lichts.\n\nAuf ihre Bitte hin willigte ich ein, mich der Mission von Rissklinge Maella anzuschließen, um diese Streitkräfte der Leere und die Hal\'hadar zu verfolgen.\n\nWir teilen eine komplizierte Geschichte mit diesen Gegnern, aber wir sind für eine Reise in diese unbekannten Gefilde gut gerüstet.\n\nDie hier Versammelten gehören zu den besten, die in der Einheit der Lichtschleier dienen.', '', 68974),
(317656, 'deDE', '', 'Tul\'amar knirscht mit den Zähnen, als sie für einen kurzen Moment zum Schweigen kommt. Ihr gutes Auge wandert zu Euch und anschließend zurück zu Tala\'saan.', 68974),
(317572, 'deDE', 'Ich werde meine... beziehungsweise unsere neue Schachfigur genau im Auge behalten.', '', 68974),
(317571, 'deDE', 'Unsere Arbeit ist noch nicht getan, doch macht Euch keine Sorgen darum, dass Impotus uns in die Quere kommt. Er wird sich in der Akropolis verschanzen, um seinen Sieg zu genießen.', '', 68974),
(317109, 'deDE', 'Dieses eisige Brachland ist schwach. Es gibt andere Welten, die deutlich einfacher und... besser geeignet wären.', '', 68974),
(316762, 'deDE', 'Rissklinge Maella hat uns gebeten, ihre Truppen auf dieser Expedition zu begleiten.\n\nVeraans Wissen über die Leere und die Operationen der Hal\'hadar machten sie zu einer wertvollen Bereicherung dieser Mission.\n\nWas mich betrifft? Nun, man kann nie wissen, wann man einen Technomanten braucht, um etwas auseinanderzunehmen!', '', 68974),
(316750, 'deDE', '', 'Die Archive in Antorus haben aufgezeigt, dass die Anwesenheit der Legion hier auf Val spärlich war. Ich kann mir nicht erklären, warum.\n\nEin Großteil dieser Welt wird von gewaltigen Hagelstürmen geschützt, die selbst den Rumpf eines Legionsschiffes aufreißen können.\n\nMindestens zwei Invasionsschiffe gingen bei ihren Versuchen, diese Welt zu erobern, verloren.\n\nSie konnten schließlich einige Festungen errichten, doch es waren kaum mehr als ferne Außenposten.\n\nAnscheinend wurden jene, die in Vals Außenposten stationiert waren, als Strafe für wiederholtes Versagen hierhergeschickt.', 68974),
(316562, 'deDE', '', '<Erzmagierin Y\'mera wirkt hochkonzentriert auf ihre Aufgabe. Ihre Hände verschwimmen, während sie Runensymbole in die Konsole eingibt.>\n\nDie Leerenenergie im Süden entstammt der Akropolis.\n\nDiesen Werten nach zu urteilen, erstreckt sich die Festung tief unter das Eis.', 68974),
(316520, 'deDE', '', 'Die Illidari kennen diese gefrorene Hölle besser als die meisten. Die Legion nannte sie \"Val\" und nutzte ihre eisigen Temperaturen für die Befragung von Gefangenen.\n\nEine kalte, tote Einöde wirkt wie der perfekte Ort für einen Domanaar, um sich zurückzuziehen.\n\n<Maella wirft einen nicht ganz subtilen Blick zu Decimus.>', 68974),
(316419, 'deDE', '<Das Leuchtfeuer hat zwei Schaltflächen für die Zielauswahl eines Teleports: Silbermond oder der Leerensturm. Widersteht dem Drang, beide gleichzeitig zu drücken.>', '<Das Leuchtfeuer hat zwei Schaltflächen für die Zielauswahl eines Teleports: Silbermond oder der Leerensturm. Widersteht dem Drang, beide gleichzeitig zu drücken.>', 68974),
(314754, 'deDE', 'Eure Gegner befinden sich hinter Euch. Kehrt um!', 'Eure Gegner befinden sich hinter Euch. Kehrt um!', 68974),
(313932, 'deDE', '', 'Rissklinge Maella starrt die Projektion von Decimus hasserfüllt an.', 68974),
(313749, 'deDE', '', 'Ist es so weit? Schickt Euch Rissklinge Maella? Ich könnte Eure Hilfe gebrauchen, bevor wir aufbrechen!\n\nIch habe unsere Lichtschleiertechnologie mithilfe eines einfachen Tarnzaubers und dieses Strangsignals modifiziert.\n\nIch glaube, in Kombination kann ich unser gesamtes Basislager verschleiern, sobald wir landen.\n\nAber zuerst brauche ich ein unsichtbares Testobjekt, um die Reichweitenbegrenzung zu prüfen.\n\nMöchtet Ihr helfen?', 68974),
(310380, 'deDE', 'Der Tod eines Imperators der Domanaar hat andere Auswirkungen als der eines sterblichen Anführers.', '', 68974),
(310377, 'deDE', '', 'Dank unserem Champion stellt Pertinax kein Problem mehr für uns dar.', 68974),
(310376, 'deDE', 'Und sollte ihr \"Imperator\" Euch mit seiner Präsenz beehren, könnt Ihr dieses Ödland gern von ihm befreien.', '', 68974),
(310375, 'deDE', '', 'Die Leerenpräsenz hier zu neutralisieren, verschafft unserem Volk die nötige Pause. Sät Chaos, Champion.', 68974),
(310366, 'deDE', 'Licht... Teufelsmagie... Leere. Das perfekte Rezept für Spannungen. Köstlich.', '', 68974),
(309048, 'deDE', 'Die Hal\'hadar haben ihre fliegenden Skiffs zum \"Schutz\" mit Energiegeschützen ausgestattet. Mal sehen, wie gut sie wirklich geschützt sind.', '', 68974),
(309020, 'deDE', '', 'Unsere lichtgeschmiedeten Späher berichten von Hinweisen auf eine alte Leerenkreatur, die einst hier hauste. Beschafft Proben für unsere Forschung.', 68974),
(309018, 'deDE', 'Eure... \"abenteuerlustigeren\" Späher wollten die flüchtigen Ressourcen dieser Welt nutzen. Vermeidet beim Sammeln irgendwelche unglücklichen Zwischenfälle.', '', 68974),
(309015, 'deDE', '', 'Eine Sabotage des Portalnetzwerks der Domanaar wird ihre Invasion in Azeroth verzögern. Macht ihnen das Leben schwer.', 68974),
(309014, 'deDE', 'Natürlich gefährdet eine weitere \"Bedrohung\" Eure Mission. Zerstört, vernichtet, siegt.', '', 68974),
(318546, 'deDE', 'Die Terrasse der Magister war immer ein Ort des Lernens.\n\nEine Bastion des Wissens, in der übertriebener Stolz oder Streitigkeiten keinen Platz hatten.\n\nAber, wie sehr ich mich auch bemühe, es fällt mir schwer, die Rückkehrer hier zu sehen und nicht...\n\n<Der Magister presst die Lippen zusammen und schweigt.>', 'Die Terrasse der Magister war immer ein Ort des Lernens.\n\nEine Bastion des Wissens, in der übertriebener Stolz oder Streitigkeiten keinen Platz hatten.\n\nAber, wie sehr ich mich auch bemühe, es fällt mir schwer, die Rückkehrer hier zu sehen und nicht...\n\n<Die Magistrix presst die Lippen zusammen und schweigt.>', 68974),
(318542, 'deDE', '<Der Hochelfenmagister seufzt, als Ihr Euch nähert.>\n\nBitte schimpft nicht mit mir, nur weil ich hier bin... Einen weiteren bösen Blick oder Kommentar ertrage ich nicht.\n\nIch will bloß Magie lernen und neue Zauber üben. Ist das denn zu viel verlangt?\n\nDieses Gezanke macht mich wahnsinnig!', '<Der Hochelfenmagister seufzt, als Ihr Euch nähert.>\n\nBitte schimpft nicht mit mir, nur weil ich hier bin... Einen weiteren bösen Blick oder Kommentar ertrage ich nicht.\n\nIch will bloß Magie lernen und neue Zauber üben. Ist das denn zu viel verlangt?\n\nDieses Gezanke macht mich wahnsinnig!', 68974),
(317974, 'deDE', 'Es war schon immer unsere Berufung, die Magie zu beherrschen und zu verstehen. Die Berufung eines Magisters.\n\nIch hoffe sehr, dass einige unserer aufgeschlosseneren Kollegen dazu beitragen können, anderen unsere Absichten bei der Erforschung der Leere näherzubringen.\n\nEs ist ja nicht so, dass wir damit drohen, diejenigen zu verbannen, die nicht an diesem Studium teilhaben wollen.', 'Es war schon immer unsere Berufung, die Magie zu beherrschen und zu verstehen. Die Berufung einer Magistrix.\n\nIch hoffe sehr, dass einige unserer aufgeschlosseneren Kollegen dazu beitragen können, anderen unsere Absichten bei der Erforschung der Leere näherzubringen.\n\nEs ist ja nicht so, dass wir damit drohen, diejenigen zu verbannen, die nicht an diesem Studium teilhaben wollen.', 68974),
(317973, 'deDE', 'Laut Veldharin untersuchten die ersten Sucher des Wissens die dunkle Präsenz, die unsere Vorfahren in Tirisfal spürten.\n\nNiemand weiß genau, was sie fanden, aber angeblich kehrten nur wenige mit unversehrtem Verstand zurück.\n\nWas auch immer sie gesehen oder gefunden haben, hat Dath\'Remar dazu veranlasst, die Leerenmagie zu verbieten.\n\nGlaubt Ihr, dass Umbric sich mit ihr beschäftigt hat? Glaubt Ihr, dass man es uns erlauben wird?', 'Laut Veldharin untersuchten die ersten Sucher des Wissens die dunkle Präsenz, die unsere Vorfahren in Tirisfal spürten.\n\nNiemand weiß genau, was sie fanden, aber angeblich kehrten nur wenige mit unversehrtem Verstand zurück.\n\nWas auch immer sie gesehen oder gefunden haben, hat Dath\'Remar dazu veranlasst, die Leerenmagie zu verbieten.\n\nGlaubt Ihr, dass Umbric sich mit ihr beschäftigt hat? Glaubt Ihr, dass man es uns erlauben wird?', 68974),
(317972, 'deDE', '<Der Magister seufzt, als Ihr Euch nähert.>\n\nBitte schimpft nicht mit mir, nur weil ich hier bin... Einen weiteren bösen Blick oder Kommentar ertrage ich nicht.\n\nIch will bloß Magie lernen und neue Zauber üben. Ist das denn zu viel verlangt?\n\nDas Gezanke macht mich wahnsinnig, und das will was heißen, immerhin habe ich in ein schwarzes Loch gestarrt!', '<Die Magistrix seufzt, als Ihr Euch nähert.>\n\nBitte schimpft nicht mit mir, nur weil ich hier bin... Einen weiteren bösen Blick oder Kommentar ertrage ich nicht.\n\nIch will bloß Magie lernen und neue Zauber üben. Ist das denn zu viel verlangt?\n\nDas Gezanke macht mich wahnsinnig, und das will was heißen, immerhin habe ich in ein schwarzes Loch gestarrt!', 68974),
(317917, 'deDE', 'Um ehrlich zu sein, bin nich nicht sicher, ob das seine Absicht war.\n\nSein Verrat gegen die Konvokation und unser Volk war abscheulich, doch ich kann mir nicht vorstellen, dass er das Omnium absichtlich beschädigen würde.\n\nEin Archiv voll mit verbotenem Wissen, das ihm so lange vorenthalten wurde, würde er nicht leichtfertig zerstören wollen.\n\nWenn überhaupt, so hätte ich erwartet, dass er versucht, das ganze Omnium zu stehlen.\n\nVielleicht hat er sich deshalb mit einem Stück davon begnügt.', '', 68974),
(317753, 'deDE', '<Er kneift die glasigen Augen zu Schlitzen zusammen.>\n\nEine... angemessene Frage, schätze ich.\n\nEs ist... es war... ein streng verbotener Wissensknoten, wie von Dath\'Remar verfügt.\n\nAls wir das erste Mal Fuß auf die Küsten von Tirisfal setzten, stießen unsre Vorfahren auf eine Finsternis, die sich an dieses Land klammerte.\n\nDas Geflüster trieb viele in den Wahnsinn, es nährte sich von unserer Paranoia und entfachte Furcht und Eifersucht unter unserem erschöpften Volk.\n\nDath\'Remar wollte verstehen, woher diese Magie kam, weshalb er die ersten der Sucher entsandte.\n\nNur wenige wissen, was sie fanden oder erlebten, doch es bewog Dath\'Remar dazu, seine Studien sofort abzubrechen.\n\nNur die vertrauenswürdigsten und renommiertesten Magister durften das Wissen innerhalb des Leerenmagiküls ergründen.', '', 68974),
(317750, 'deDE', 'Eine sehr gute Frage! Mal sehen...\n\nWir haben da natürlich das Arkanmagikül. Tausende Jahre des Wissens der Hochgeborenen verliehen unserem frischgebackenen Volk die Ressourcen, um in diesem neuen Land zu gedeihen.\n\nWir haben das Feuermagikül und andere elementare Magiküle: die natürlichen Grundlagen unserer Welt.\n\nWir haben eine kuriose Sammlung heiligen Wissens innerhalb des Lichtmagiküls. Die Hohepriester von Silbermond haben viel zu seinem Verständnis beigetragen.\n\nUnd, da jeder danach fragt, es gibt auch noch die verbotenen Magiküle...\n\nLeere. Teufelsmagie. Nekromantie.. obwohl ich mir vorstellen kann, dass einige der Beschränkungen in diesem Bereich vielleicht... gelockert werden.\n\n<Veldharin runzelt nachdenklich die Stirn.>', '', 68974),
(317749, 'deDE', 'Ich würde Euch die Plakette auf dem Omnium ans Herz legen. Sie fasst Dath\'Remars Absichten recht gut zusammen.\n\nAber um es kurz zu machen: Seine Gründe waren vielfältig, seine Ambitionen mutig und sein Ziel so klar wie der Himmel über Immersang.\n\nDath\'Remar hatte in seiner Jugend viel gesehen und fürchtete sich nicht vor den magischen Kräften unserer Welt.', '', 68974),
(317748, 'deDE', 'Natürlich, und nicht nur für das Omnium!\n\nIch habe zwei Brüder und meine geliebte Schwester verloren, als die Stadt fiel. Alle drei waren Magister...\n\nIch half dem jungen Prinzen bei der Wiederbelebung... Erweckung? Es war so... kalt.\n\nDoch was wir auch versuchten, es... weigerte sich einfach. Selbst mit diesem Chiffrierschlüssel antwortete es nicht.\n\nNachdem es versiegelt wurde, wollte ich den überlebenden Magistern bei der Wiederherstellung der Terrasse helfen... doch sie bestanden darauf, ich solle mich ausruhen.\n\nUnd das tat ich auch viele Jahre lang auch. Wobei einige davon... nicht so schön waren. Doch schließlich kehrte ich zurück und der junge Rommath hatte keine Lust, mich aufzuhalten.\n\nDie Rückkehr aus dem Ruhestand ist genau das, was ich nach all den Jahren gebraucht habe!', '', 68974),
(317746, 'deDE', 'Nun, ich meinte eigentlich Fragen bezüglich des Omniums, nicht über mich selbst. Aber wenn Ihr es unbedingt wissen wollt...\n\nIch bin Hüter Veldharin, zum Hüter des Wissens ernannt durch Großmagistrix... ähm... wer war das noch gleich?\n\nGroßmagistrix Mo... nein, die war es nicht. Äh... tja, wie auch immer. Ist schon ein paar Großmagister her. Ich habe den Überblick verloren.\n\nNach dem Zweiten Krieg wurde ich... dazu ermutigt, mich zur Ruhe zu setzen. Angeblich wollte Anasterian, dass ich \"meine vielen verbleibenden Tage genießen\" sollte.\n\nWas seine Art war zu sagen, dass ich viel zu alt für diese Position war. Also zog ich zu meiner Tochter, Elsharin.\n\nSie diente als Sucherin des Wissens und Botschafterin des Magisteriums für das Magiersanktum in Sturmwind.', '', 68974),
(317744, 'deDE', 'Willkommen im Lycaneum!\n\nIhr befindet Euch in der Anwesenheit grenzenlosen Wissens und unendlichen magischen Potenzials!\n\nIch rede natürlich vom Omnium der Sonnenwanderer. \n\nIch bin lediglich sein Hüter und habe die Aufgabe, sämtliche jungen Magister auf ihrer magischen, akademischen Reise anzuleiten.\n\nFalls Ihr Fragen habt, müsst Ihr sie mir einfach nur stellen.', '', 68974),
(317738, 'deDE', 'Wieso heißen sie wohl Magiküle? Warum nicht Manaküle? Moment, das klingt wie Maniküre.\n\nOmniküle? Oder doch eher Omni... kuhle?\n\nBei Dath\'Remar, habe ich sie etwa die ganze Zeit falsch ausgesprochen?', 'Wieso heißen sie wohl Magiküle? Warum nicht Manaküle? Moment, das klingt wie Maniküre.\n\nOmniküle? Oder doch eher Omni... kuhle?\n\nBei Dath\'Remar, habe ich sie etwa die ganze Zeit falsch ausgesprochen?', 68974),
(317730, 'deDE', 'Ich habe nicht mehr so viel magisches Chaos auf der Terrasse erlebt, seit... nun... Eurem Raubüberfall mit Magister Umbric.\n\n<Der Zauberbrecher mustert Euch von oben bis unten.>\n\nBenehmt Euch diesmal.', 'Ich habe nicht mehr so viel magisches Chaos auf der Terrasse erlebt, seit... nun... Eurem Raubüberfall mit Magister Umbric.\n\n<Die Zauberbrecherin mustert Euch von oben bis unten.>\n\nBenehmt Euch diesmal.', 68974),
(317724, 'deDE', 'Seht Euch in diesen Hallen gut vor, $C. \n\nDies mag die Terrasse der Magister sein, doch die Regeln der Magie werden dennoch rigoros durchgesetzt.', 'Seht Euch in diesen Hallen gut vor, $C. \n\nDies mag die Terrasse der Magister sein, doch die Regeln der Magie werden dennoch rigoros durchgesetzt.', 68974),
(317723, 'deDE', '<Der Zauberbrecher kneift die Augen zusammen und schmunzelt.>\n\nKeine Sorge, $n. Ich werde meine Gleve nicht gegen Euch erheben.\n\nMan sagte mir, Ihr hättet bei Eurem letzten Besuch über die Vollmacht des Lordregenten verfügt. Wisset, dass meine Antwort nicht persönlich war.\n\nIch halte mich an den Eid, den die Zauberbrecher abgelegt haben, und diese... unglückliche Abfolge von Ereignissen auf der Terrasse hätte eine Angelegenheit zwischen den Höfen und den Magistern sein sollen, nicht zwischen Euch und mir.\n\nIch weiß es allerdings zu schätzen, dass Ihr mich nicht tötet.', '', 68974),
(317722, 'deDE', '<Rommath kneift für einen Moment die Augen zusammen.>\n\nVon Umbric und seinen... Anhängern wird erwartet werden, dass sie sich bezüglich des Omniums an die Vorschriften halten.\n\nIch werde keine magische Demonstration der Schrecken der Leere dulden, nur weil die Ren\'dorei sich nicht an Regeln halten können.\n\nSo wenig Vertrauen ich auch in den Weg habe, den Umbric eingeschlagen hat, bin ich dennoch geneigt, ihm zumindest zu vertrauen... vorerst.\n\nDa er sich sicher ist, dass seine Anhänger die Leere beherrschen können, eröffnet das neue Möglichkeiten für... fundierte Diskussionen bezüglich des Leerenmagiküls.\n\nDoch ich werde nicht zulassen, dass Leerenmagie ein neues Studienfach für die Magister der Terrasse wird!', '', 68974),
(317721, 'deDE', 'Nur den Magistern ist es gestattet, das Wissen darin zu studieren, und selbst sie sind dabei Beschränkungen unterworfen.\n\nDath\'Remar selbst hat vor Generationen Regeln und Vorschriften erlassen.\n\nSo stellte er sicher, dass gefährliche und unvorhersehbare Magie aufgezeichnet und katalogisiert wird und half uns dabei, uns besser vor der Unberechenbarkeit dieser Mächte zu schützen.\n\nAllerdings gab es eine Zeit, als der Zugang zum Teufelsmagikül strikt verboten war.\n\nWie schnell sich die Dinge doch ändern können...', '', 68974),
(317719, 'deDE', '<Umbric lächelt und sieht zu Rommath.>\n\nRommath mag... meine Forschung gerade so tolerieren, doch das Omnium wurde stets gut durch Sicherheitsmaßnahmen und Regulierungen geschützt.\n\nEs war glücklicherweise nie ein öffentlich zugängliches Kompendium für alles Magische.\n\nMich graust es bei dem Gedanken, was Dar\'Khan alles hätte erreichen können, hätte man ihm Zugang gewährt.\n\nDie aktuellen Regeln bestehen seit den Tagen von Dath\'Remar.\n\nSeine ersten Begegnungen mit der Leere oder der Zerstörung durch Teufelsmagie, die er während des Kriegs der Ahnen erlebte, sind genau der Grund, weshalb derlei Magie verboten wurde.\n\nDavon abgesehen gibt es vielleicht doch noch Gesprächsbedarf.', '', 68974),
(317717, 'deDE', 'Das ist eine Frage, die wir alle uns gestellt haben, seit es verstummt ist.\n\nNiemand weiß, was genau geschehen ist. Wir kennen lediglich den Zustand, in dem es gefunden wurde.\n\nIch war nicht dabei, als die Terrasse fiel... als Dar\'Khan erschien... doch ich wurde Zeuge der Nachwirkungen.\n\nWir hatten das Omnium noch nie so leer erlebt. Nicht ein Schimmer von Macht, kein Magikül in Sicht.\n\nEin leerer, stummer Rahmen. Es war... verstörend, gelinde gesagt.', '', 68974),
(317715, 'deDE', 'Als wir es fanden, war es lediglich ein leerer Rahmen in den Trümmern. Keine Magiküle. Kein runischer Schimmer.\n\nAbgesehen von dem Unrat, den Dar\'Khans Gemetzel hinterlassen hatte, wirkte es leblos.\n\nDie Magiküle wurden als Erweiterungen des Omniums entworfen. Wir sahen sie nie als Teile an, die verloren gehen konnten.\n\nAls das Relikt erwachte und die Magiküle wieder erschienen, stellten wir fest, dass die zentrale Matrix leer war.\n\nSolch eine Anomalie hatten wir noch nie zuvor gesehen.\n\nAuf welches Magikül auch immer als letztes zugegriffen wurde, es war schlicht fort oder zerstört. Oder in diesem Fall, gestohlen worden.', '', 68974),
(317714, 'deDE', 'Zuerst ja.\n\nWir wussten, dass er zur Terrasse gekommen war, um die Konvokation abzuschlachten. Die Beweise dafür waren als Spritzer auf den Wänden und dem Omnium selbst verteilt.\n\nDoch als wir sein Studierzimmer und Heim durchsuchten, fanden wir lediglich Hinweise auf seine Leidenschaft für dunklere Magien vor.\n\nUmbric wies später darauf hin, dass Drathirs Motivation in Macht und Wissen lag; das Omnium zu beschädigen, passte nicht zu seinen... Ambitionen.', '', 68974),
(317713, 'deDE', 'Das... kann ich nicht beantworten.\n\nDoch wir haben nichts unversucht gelassen, das Omnium wiederzubeleben. Nicht einmal der Chiffrierschlüssel der Sonnenwanderer konnte etwas bewirken.\n\nKael\'thas... trauerte.\n\nWie wir alle hatte er in so kurzer Zeit so viel verloren.\n\nEr wollte unbedingt Antworten für unsere Notlage finden. Für unser Volk.\n\nDas Wissen im Omnium hätte uns helfen können... Es hätte den Prinzen vielleicht sogar anleiten können.\n\nDoch als es stumm blieb, befanden wir uns in einer Sackgasse.', '', 68974),
(316792, 'deDE', 'Chiffrierschlüssel der Sonnenwanderer nicht erkannt. Spiegelecho-Abbild aktiviert.', 'Chiffrierschlüssel der Sonnenwanderer nicht erkannt. Spiegelecho-Abbild aktiviert.', 68974),
(315312, 'deDE', 'Dies ist der Morgensternturm, in dem Dar\'Khan Drathir aufgewachsen ist. Einst war dies ein stiller, freundlicher Ort.\n\nNach meiner Verbannung aus Silbermond habe ich mehrere Bruchstücke von Dar\'Khans Forschung über die Leere ausfindig gemacht, was mich hierher führte.\n\nAnscheinend hat er einen Großteil seiner Forschung im Geheimen durchgeführt. Auf der Spitze dieses Turms habe ich zum ersten Mal den Riss nach Telogrus geöffnet.\n\nWer hätte gedacht, dass sich hier weitere Geheimnisse verborgen halten...', '', 68974),
(314998, 'deDE', 'Wir haben noch nie einen Sucher ernannt, der nicht den Magistern angehört, aber Ihr seid... besonders qualifiziert.\n\nAls $uSucher:Sucherin; werdet Ihr Forschungsaufgaben erhalten, entweder von mir oder Umbric.\n\nIm Gegenzug für den Abschluss dieser Aufgaben werden wir Euch eine Reihe mächtiger Runenverzauberungen zur Verfügung stellen, um Eure Kräfte zu verstärken.\n\nIhr findet diese Runen in Eurem Omniumfolianten. Die Entscheidung, welche Ihr davon ermächtigt, liegt natürlich ganz bei Euch.\n\nHabt Ihr noch Fragen?', '', 68974),
(314900, 'deDE', '<Rommath blickt zu dem stummen Omnium.>\n\nFast geschafft. Mit Belo\'virs Chiffrierschlüssel und dem verschollenen Leerenmagikül, welches Ihr und Umbric gefunden habt, bleibt nur noch eines.\n\nJetzt oder nie, $n. Seit Ihr bereit?', '', 68974),
(314899, 'deDE', 'Jahrelang habe ich das Omnium studiert. Wie jeder Magister vor mir lernte ich alles, was es zu lernen gab: Runen, Zauber, Formeln, einfach alles.\n\nSein Verstummen war ein dunkler Tag, aus vielerlei Gründen. Ich hätte nie geglaubt, dass es je wieder voller Leben summen würde. Kaum zu glauben, wie weit wir gekommen sind.', '', 68974),
(314791, 'deDE', 'Belo\'vir scheint Anweisungen zurückgelassen zu haben, wie sein Tresor zu öffnen ist... Anweisungen, die lange auf mich gewartet haben.\n\nWie ich meinen Vorgänger kenne, sind sie ohne Zweifel genauso fortgeschritten, wie sein meisterhaftes Geschick mit Spiegelbildzaubern.\n\nEine Herausforderung, die wir untereinander aufteilen müssen. Ich werde mich oben in meinem Büro den komplexeren Schutzzaubern widmen.\n\nKönnt Ihr meine Spiegelbilder dabei unterstützen, die drei hier unten aufzulösen?', '', 68974),
(314746, 'deDE', 'Ich frage mich, wie lange Dar\'Khan wohl nach den verbotenen Geheimnissen im Inneren des Leerenmagiküls gesucht hat.\n\nAls wir uns den Magistern anschlossen, hielt man uns einen Vortrag darüber, welche Schulen der Magie und die damit verbundenen Magiküle der Allgemeinheit strengstens untersagt waren.\n\nDar\'Khan hatte bereits während unserer frühen Tage in Dalaran seine Vorliebe für die Leere gezeigt, daher wusste ich zumindest von seiner Faszination.\n\nHat er sie schon seit dem Tag begehrt, als wir das Lycaneum zum ersten Mal betraten?\n\nOder war es eine übermütige Entscheidung in letzter Sekunde, die er in die Tat umsetzte, während er seine Brüder auf der Terrasse abschlachtete?', '', 68974),
(314744, 'deDE', 'Vor langer Zeit glaubte ich, jedes Geheimnis ausfindig gemacht zu haben, das Dar\'Khan an diesem Ort verborgen hat. Die heutigen Ereignisse waren sicherlich... unerwartet.\n\nAls Vorsichtsmaßnahme werde ich überprüfen, ob sich hier noch etwas verborgen hält. Rommath wird garantiert danach fragen.\n\nIch werde die Reste unseres Rituals beseitigen und Euch bei der Terrasse der Magister treffen, nachdem Ihr Rommath dabei geholfen habt, Belo\'virs Chiffrierschlüssel zurückzuholen.', '', 68974),
(314678, 'deDE', 'Mein Verdacht hat sich bewahrheitet... Spürt Ihr es, $n? Dieses kalte, entfernte Trommeln... wie ein dumpfer Herzschlag.\n\nEs könnte das Ziel unserer Suche sein, verborgen vor unseren Blicken.\n\nMit dem richtigen Zauber und etwas Konzentration kann die Leere die Geheimnisse enthüllen, die Dar\'Khan hier vielleicht noch begraben hat.\n\nWährend Ihr die Anker verbindet, werde ich den Zauber vollenden.\n\nDoch gebt Acht, die Leere zieht bereits an uns und ruft uns an unser Ziel.', '', 68974),
(310354, 'deDE', 'Wir müssen seine Schutzvorkehrungen ausschalten. Ich treffe unseren Champion dort.', '', 68974),
(310059, 'deDE', 'Ob Arkan-, Teufels- oder selbst Licht- oder Leerenmagie: Dath\'Remar erschuf das Omnium, um darin Wissen zu bewahren.', '', 68974),
(317919, 'deDE', 'Ich kann mir vorstellen, dass das auf viele zutrifft.\n\nNormalerweise würde ich alle Fragen an unseren frisch aus dem Ruhestand zurückgekehrten Hüter des Wissens, Veldharin, weiterleiten.\n\nDoch dank Eurer Rolle bei der Wiederherstellung des Omniums werde ich Eure Neugier stillen.', '', 68974),
(317754, 'deDE', 'Ach ja. Das Teufelsmagikül. Ein verbotener Wissensknoten, zumindest war es das einmal.\n\nDie Teufelsmagie war eine der ersten Magieformen, die Dath\'Remar als Katalysator für die Erschaffung des Omniums angibt.\n\nEr sah ihr Potenzial... und ihren Schrecken während der Tage der Hochgeborenen. Er sah die Kreaturen aus dem Jenseits, die Teufelsmagie nutzten.\n\nAls die Zeit gekommen war, sah er während dieser letzten Tage des Kriegs der Ahnen die zerstörerische Wahrheit von Teufels- und Arkanmagie.\n\nEr wollte niemals wieder zulassen, dass sein Volk von solch einer zerstörerischen, unbekannten Macht geblendet wird.\n\nMit der Zeit wurde das Wissen über die Teufelsmagie und die Brennende Legion zwischen den Magistern und dem Rat von Tirisfal geteilt.\n\nDoch von wenigen Auserwählten abgesehen, war es verboten, das Teufelsmagikül zu studieren.\n\nOh, wie sich die Zeiten doch ändern sollten...', '', 68974),
(317573, 'deDE', 'Diese Welt... all ihr Potenzial... ist nun mein.', '', 68974),
(309931, 'deDE', 'Waldläufer, wappnet Euch! Zeigt diesen Monstern, warum Ihr auserwählt wurdet, die Enklave zu beschützen!', 'Waldläufer, wappnet Euch! Zeigt diesen Monstern, warum Ihr auserwählt wurdet, die Enklave zu beschützen!', 68974),
(307084, 'deDE', 'Ah, $n.\n\nEs ist schön, an diesem Tisch mal ein weniger finsteres Gesicht zu sehen. Sie dulden mich wieder in meiner Stadt, aber glaubt mir: Rommath könnte jederzeit wieder eins seiner speziellen Blinzelgeschosse benutzen.\n\nEr hat damals nämlich \'Blinzeln\' mit \'Arkane Geschosse\' kombiniert, um jedem, der töricht genug war, ihn zu einem Magierduell herauszufordern, eine Lektion zu erteilen.\n\nEr gibt es nicht gern zu, aber ich habe ihm beigebracht, eine Unsichtbarkeitszauberschicht über die Geschosse zu legen, damit man sie nicht kommen sieht.\n\nWie dem auch sei, Lor\'themar hat mir erlaubt, hier zu sein, und ich genieße das Unbehagen, das meine bloße Anwesenheit verursacht.', '', 68974),
(306595, 'deDE', 'Wir... Lor\'themar muss erfahren, was geschehen ist. Ihr geht voraus.', '', 68974),
(304405, 'deDE', 'In Zeiten von Krieg und Zwietracht sind unsere Urtumbeschützer eine unbeugsame Kraft auf dem Schlachtfeld.\n\nEs ist nur sehr aufwendig, sie wachzukriegen.\n\nIch werde veranlassen, dass die Schlachtpfleger des Ältesten Grünborke Euch folgen. Sucht nach großen Steinen und Felsblöcken, die der Älteste auf unsere Gegner schleudern kann.\n\nEr weigert sich aufzuwachen, bis er etwas zum Werfen hat.', 'In Zeiten von Krieg und Zwietracht sind unsere Urtumbeschützer eine unbeugsame Kraft auf dem Schlachtfeld.\n\nEs ist nur sehr aufwendig, sie wachzukriegen.\n\nIch werde veranlassen, dass die Schlachtpfleger des Ältesten Grünborke Euch folgen. Sucht nach großen Steinen und Felsblöcken, die der Älteste auf unsere Gegner schleudern kann.\n\nEr weigert sich aufzuwachen, bis er etwas zum Werfen hat.', 68974),
(303273, 'deDE', '', 'Die Urtumbeschützer bieten in der Schlacht mächtige Belagerungsunterstützung, welche die hinteren Reihen des Feindes dezimiert.\n\nDie Horde kennt ihre zerstörerische Kraft nur zu gut.', 68974),
(300503, 'deDE', '', 'Das ist eigentlich nicht möglich. Ich habe sie magisch zu Ulen gesandt, meinem Seneschall. Vielleicht gibt es in Suramar Probleme.', 68974),
(292933, 'deDE', 'Nun... Es war viel Arbeit, und Ihr habt es verdient.', '', 68974),
(289958, 'deDE', '', 'Der Silberbund kehrt ein letztes Mal nach Silbermond zurück.', 68974);
