INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(3033, 'deDE', 'Gequälter Fresser', '|cFFFFD200Zonen:|r Val und Naigtal|n|cFFFFD200Erfolg:|r Heroische Konfrontationen|n|cFFFFD200Verkäufer:|r Kifaan|n|cFFFFD200Kosten:|r 15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 'Sowohl die Domanaar als auch die Astralen haben versucht, diesen Fresser einzufangen, doch jedes Mal sind sie gescheitert. Nun ist der gequälte Fresser erfüllt mit Leerenenergie und bereit, Chaos zu entfesseln.', 68974),
(2990, 'deDE', 'Nethergeschmiedete Nullpanzerung', '|cFFFFD200Erfolg:|r Eine Reise durch die Sterne|n|cFFFFD200Zone:|r Naigtal|n|cFFFFD200Verkäufer:|r Kifaan|n|cFFFFD200Kosten:|r 15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 'Von den Lichtgeschmiedeten zusammengefügt, von den Hal\'hadar zerlegt und von einem Technomanten wiederhergestellt. Eine Matrix aus Licht, Leere und arkanen Strudeln befindet sich innerhalb dieser erneuerten Kriegspanzerung.', 68974),
(2988, 'deDE', 'Sternenschnitzer des Leerenwirkers', '|cFFFFD200Erfolg:|r Eine Reise um die Sterne|n|cFFFFD200Zone:|r Val|n|cFFFFD200Verkäufer:|r Kifaan|n|cFFFFD200Kosten:|r 15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 'Diese Spitzentechnologie der Leerenwirkertransportation war einst ein Status- und Machtsymbol unter hochrangigen Domanaar. Nachdem ihr Erfinder auf mysteriöse Weise verschwand, galt es als unziemlich, sie für Kernweltversammlungen zu nutzen.', 68974),
(2975, 'deDE', 'X-TREM Feuerwerkrakete des Bilgewasserkartells', '|cFFFFD200Handelsposten|r', 'Die Ingenieure von Lorenhall waren so sehr damit beschäftigt, ob sie eine schnellere Rakete bauen KÖNNTEN oder nicht, dass sie nicht darüber nachdachten, ob sie es sollten.', 68974);
